WITH with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_new_burst_tier, APPROX_PERCENTILE(session_id, ARRAY(0.25, 0.5, 0.75)) AS session_id_quartiles, COUNT(CASE WHEN browser = 'Firefox' THEN 1 END) AS firefox_count FROM sessions_sessions GROUP BY year_start, is_new_burst_tier HAVING COUNT(CASE WHEN browser = 'Firefox' THEN 1 END) > 1
